/// ROXConfigurationManager provides centralized management of multiple SDK configurations.
/// It maintains a thread-safe registry of configurations and handles the default configuration
/// for backward compatibility with existing code.
/// Key features:
/// <ul>
///   <li>
///     Thread-safe configuration management
///   </li>
///   <li>
///     Support for multiple independent configurations
///   </li>
///   <li>
///     Backward compatibility via default configuration
///   </li>
///   <li>
///     Automatic namespacing of properties and flags
///   </li>
/// </ul>
/// Example usage:
/// \code
/// // Setup multiple configurations
/// try ROXConfigurationManager.setup(withKey: "prod_key", name: "production")
/// try ROXConfigurationManager.setup(withKey: "stage_key", name: "staging")
///
/// // Access configurations via ROX.using
/// if let prodOps = ROX.using("production") {
///     prodOps.setCustomStringProperty(key: "env", value: "prod")
///     prodOps.register(FeaturesContainer())
/// }
///
/// if let stageOps = ROX.using("staging") {
///     stageOps.setCustomStringProperty(key: "env", value: "stage")
///     stageOps.register(FeaturesContainer())
/// }
///
/// // Check if configuration exists
/// if ROXConfigurationManager.exists("production") {
///     // Use the configuration
/// }
///
/// // Get default configuration (for backward compatibility)
/// if let defaultConfig = ROXConfigurationManager.getDefault() {
///     // Use default configuration
/// }
///
/// \endcodeFor configuration-specific operations, use <code>ROXOperations</code> obtained via <code>ROX.using(_:)</code>.
/// See <code>ROXOperations</code> and <code>ROXConfiguration</code> for more details.
