/// ROXOperations provides configuration-specific operations that mirror the static ROX methods.
/// Each instance is associated with a specific ROXConfiguration and provides methods to
/// manage feature flags, custom properties, and other SDK operations for that configuration.
/// This enables isolated management of features and properties across different configurations.
/// Key features:
/// <ul>
///   <li>
///     Configuration-specific property management
///   </li>
///   <li>
///     Isolated feature flag registration
///   </li>
///   <li>
///     Computed property support
///   </li>
///   <li>
///     Global context management
///   </li>
///   <li>
///     Flag overrides and dynamic API access
///   </li>
/// </ul>
/// Example usage:
/// \code
/// // Get operations for a specific configuration
/// if let ops = ROX.using("production") {
///     // Set static properties
///     ops.setCustomStringProperty(key: "env", value: "prod")
///     ops.setCustomBooleanProperty(key: "enabled", value: true)
///     
///     // Set computed properties
///     ops.setCustomStringProperty(key: "region") { _, ctx in
///         return getCurrentRegion()
///     }
///     
///     // Register feature containers
///     ops.register(FeaturesContainer())
///     
///     // Manage flags
///     ops.fetch()
///     ops.unfreeze()
///     
///     // Access flag overrides
///     let overrides = ops.overrides()
///     overrides.setOverride("flag_key", value: true)
/// }
///
/// \endcodeROXOperations instances should be obtained via <code>ROX.using(_:)</code> rather than created directly.
